steps.command:
set -euo pipefail
python - <<'PY'
import ast,hashlib,json,pathlib
root=pathlib.Path('.').resolve(); source=root/'canonical/runtime'
report=json.loads((root/'canonical/astra_runtime/tmp/PYTHON_SOURCE_AUDIT_VERIFY.json').read_text())
assert report['schema']=='PROJECT_BRAIN_PYTHON_SOURCE_AUDIT_V1'
actual={}
all_imports=set(); fn=cl=0
for p in sorted(source.rglob('*.py')):
 raw=p.read_bytes(); tree=ast.parse(raw.decode('utf-8'),filename=str(p))
 funcs=sorted(n.name for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)))
 classes=sorted(n.name for n in tree.body if isinstance(n,ast.ClassDef))
 mods=set()
 for n in tree.body:
  if isinstance(n,ast.Import): mods.update(a.name.split('.')[0] for a in n.names)
  elif isinstance(n,ast.ImportFrom) and n.module: mods.add(n.module.split('.')[0])
 key=str(p.relative_to(root)).replace('\\','/')
 actual[key]={'sha256':hashlib.sha256(raw).hexdigest(),'imports':sorted(mods),'functions':funcs,'classes':classes}
 all_imports.update(mods); fn+=len(funcs); cl+=len(classes)
reported={x['path']:{k:x[k] for k in ('sha256','imports','functions','classes')} for x in report['files']}
assert reported==actual, {'missing':sorted(set(actual)-set(reported)),'extra':sorted(set(reported)-set(actual))}
assert report['totals']=={'files':len(actual),'functions':fn,'classes':cl,'distinct_imported_modules':len(all_imports)}
assert report['distinct_imported_modules']==sorted(all_imports)
print(json.dumps({'verified':True,'files':len(actual),'functions':fn,'classes':cl,'distinct_imported_modules':len(all_imports)},sort_keys=True))
print('PYTHON_SOURCE_AUDIT_INDEPENDENTLY_VERIFIED')
PY
